#!/usr/bin/env bash
# ─────────────────────────────────────────────────────────────────
# Setup script — bndes-naval-mcp
# Cria toda a estrutura do projeto na pasta atual.
#
# Uso:
#   mkdir -p ~/projetos/bndes-naval-mcp
#   cd ~/projetos/bndes-naval-mcp
#   bash setup.sh
# ─────────────────────────────────────────────────────────────────
set -euo pipefail

echo '📦 Criando estrutura de diretórios...'
mkdir -p \
  docs \
  packages/db/src/schema \
  packages/db/src/seed \
  packages/mcp/src/tools \
  packages/mcp/src/prompts \
  packages/mcp/scripts \
  packages/agents/src/prompts

echo '  → package.json'
echo '' | base64 -d > 'package.json'

echo '  → .env.example'
echo '' | base64 -d > '.env.example'

echo '  → railway.toml'
echo '' | base64 -d > 'railway.toml'

echo '  → claude-desktop-config.json'
echo '' | base64 -d > 'claude-desktop-config.json'

echo '  → packages/db/package.json'
echo '' | base64 -d > 'packages/db/package.json'

echo '  → packages/db/src/schema/documents.ts'
echo '' | base64 -d > 'packages/db/src/schema/documents.ts'

echo '  → packages/db/src/schema/shipyards.ts'
echo '' | base64 -d > 'packages/db/src/schema/shipyards.ts'

echo '  → packages/db/src/client.ts'
echo '' | base64 -d > 'packages/db/src/client.ts'

echo '  → packages/db/src/seed/catalog.ts'
echo '' | base64 -d > 'packages/db/src/seed/catalog.ts'

echo '  → packages/mcp/package.json'
echo '' | base64 -d > 'packages/mcp/package.json'

echo '  → packages/mcp/src/embeddings.ts'
echo '' | base64 -d > 'packages/mcp/src/embeddings.ts'

echo '  → packages/mcp/src/tools/search.ts'
echo '' | base64 -d > 'packages/mcp/src/tools/search.ts'

echo '  → packages/mcp/src/tools/shipyard.ts'
echo '' | base64 -d > 'packages/mcp/src/tools/shipyard.ts'

echo '  → packages/mcp/src/tools/verify-cite.ts'
echo '' | base64 -d > 'packages/mcp/src/tools/verify-cite.ts'

echo '  → packages/mcp/src/server.ts'
echo '' | base64 -d > 'packages/mcp/src/server.ts'

echo '  → packages/mcp/scripts/ingest.ts'
echo '' | base64 -d > 'packages/mcp/scripts/ingest.ts'

echo '  → packages/agents/src/prompts/index.ts'
echo '' | base64 -d > 'packages/agents/src/prompts/index.ts'

echo '  → packages/agents/src/orchestrator.ts'
echo '' | base64 -d > 'packages/agents/src/orchestrator.ts'

echo '  → packages/agents/src/example.ts'
echo '' | base64 -d > 'packages/agents/src/example.ts'

echo ''
echo '✓ Arquivos criados. Próximos passos:'
echo ''
echo '  1. Editar .env com DATABASE_URL, VOYAGE_API_KEY e DOCS_PATH'
echo '  2. Copiar os .md dos documentos para docs/'
echo '  3. npm install'
echo '  4. npm run db:push'
echo '  5. npm run ingest'
echo '  6. npm run dev'
echo ''